import os, hashlib, json, time
from pathlib import Path
from collections import defaultdict

CHUNK = 1024 * 1024

def sha256_file(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        while True:
            b = f.read(CHUNK)
            if not b:
                break
            h.update(b)
    return h.hexdigest()

def ext_of(p: Path) -> str:
    suf = "".join(p.suffixes).lower()
    return suf if suf else "(none)"

def walk_tree(root: Path, skip_dir_names=frozenset()):
    records = []
    errors = []
    if not root.exists():
        return records, [f"MISSING:{root}"]
    for dirpath, dirnames, filenames in os.walk(root, onerror=lambda e: errors.append(str(e))):
        dirnames[:] = [d for d in dirnames if d not in skip_dir_names and not d.startswith(".git")]
        dirnames.sort()
        for name in sorted(filenames):
            if name == ".DS_Store":
                continue
            fp = Path(dirpath) / name
            try:
                st = fp.stat()
            except OSError as e:
                errors.append(f"{fp}: {e}")
                continue
            rec = {
                "path": str(fp),
                "rel": str(fp.relative_to(root)) if str(fp).startswith(str(root)) else str(fp),
                "name": name,
                "size": st.st_size,
                "mtime_epoch": int(st.st_mtime),
                "ext": ext_of(fp),
                "is_symlink": fp.is_symlink(),
            }
            if fp.is_symlink():
                rec["sha256"] = None
                rec["symlink_target"] = os.readlink(fp)
            elif fp.is_file():
                rec["sha256"] = sha256_file(fp)
            else:
                rec["sha256"] = None
            records.append(rec)
    return records, errors

repo = Path("/Users/frnkhrz/Peak_Trade")
trees = {
    "P1_docs_forensics": repo / "docs/forensics",
    "P1_docs_forensic": repo / "docs/forensic",
    "P1_forensic": repo / "forensic",
    "P1_forensics": repo / "forensics",
}
p5_root = Path("/Users/frnkhrz/Documents/Peak_Trade/forensics")

out = {
    "generated_at_unix": int(time.time()),
    "trees": {},
    "errors": {},
}

t0 = time.time()
for key, root in trees.items():
    recs, errs = walk_tree(root)
    out["trees"][key] = {
        "root": str(root),
        "exists": root.exists(),
        "file_count": len(recs),
        "byte_sum": sum(r["size"] for r in recs),
        "records": recs,
    }
    out["errors"][key] = errs
    print(f"{key} files={len(recs)} bytes={out['trees'][key]['byte_sum']} errs={len(errs)} elapsed={time.time()-t0:.1f}s")

recs, errs = walk_tree(p5_root)
out["trees"]["P5_documents_peak_trade_forensics"] = {
    "root": str(p5_root),
    "exists": p5_root.exists(),
    "file_count": len(recs),
    "byte_sum": sum(r["size"] for r in recs),
    "records": recs,
    "ASSIGNED_AS_P2": False,
    "NOTE": "Evidence-backed local path from SW-R-002 preservation binding; NOT Owner-literal Peak Trade Forensik",
}
out["errors"]["P5_documents_peak_trade_forensics"] = errs
print(f"P5 files={len(recs)} bytes={out['trees']['P5_documents_peak_trade_forensics']['byte_sum']} errs={len(errs)}")

# Desktop evidence-backed originals from source_identities (existence/hash only)
desktop_candidates = [
    "/Users/frnkhrz/Desktop/PEAK_TRADE_TEMPORARY_FORENSIC_WORKING_RUNBOOK.md",
    "/Users/frnkhrz/Desktop/PEAK_TRADE_FORENSIC_STEP15_NON_AUTHORITATIVE_TRANSFORMATION_INVARIANT_CONTRACT.md",
]
desk = []
for p in desktop_candidates:
    fp = Path(p)
    item = {"path": p, "exists": fp.exists()}
    if fp.exists() and fp.is_file():
        st = fp.stat()
        item.update({"size": st.st_size, "mtime_epoch": int(st.st_mtime), "sha256": sha256_file(fp)})
    desk.append(item)
    print("DESKTOP", item)
out["p5_desktop_evidence_bound_candidates"] = desk

# Hash index: sha256 -> list of locators
idx = defaultdict(list)
for tkey, t in out["trees"].items():
    for r in t["records"]:
        if r.get("sha256"):
            idx[r["sha256"]].append({"tree": tkey, "path": r["path"], "size": r["size"], "name": r["name"]})

cross = []
for sha, locs in idx.items():
    trees_present = sorted({l["tree"] for l in locs})
    has_repo = any(t.startswith("P1_") for t in trees_present)
    has_p5 = "P5_documents_peak_trade_forensics" in trees_present
    if has_repo and has_p5:
        cross.append({"relation": "BYTE_IDENTICAL", "sha256": sha, "size": locs[0]["size"], "name": locs[0]["name"], "locators": locs})

out["cross_byte_identical_p1_p5"] = cross
print("BYTE_IDENTICAL_P1_P5", len(cross))
for c in cross:
    print("  ", c["name"], c["sha256"][:16], "nloc", len(c["locators"]))

# Same basename different hash between P5 and P1
p5_by_name = {}
for r in out["trees"]["P5_documents_peak_trade_forensics"]["records"]:
    p5_by_name.setdefault(r["name"], []).append(r)

repo_by_name = {}
for tkey in trees:
    for r in out["trees"][tkey]["records"]:
        repo_by_name.setdefault(r["name"], []).append({"tree": tkey, **r})

same_name_diff = []
same_name_unknown = []
for name, p5s in p5_by_name.items():
    if name not in repo_by_name:
        continue
    p5_shas = {x["sha256"] for x in p5s if x.get("sha256")}
    repo_shas = {x["sha256"] for x in repo_by_name[name] if x.get("sha256")}
    if not p5_shas or not repo_shas:
        same_name_unknown.append(name)
        continue
    if p5_shas & repo_shas:
        continue  # at least one byte-identical pair; already in cross
    same_name_diff.append({
        "name": name,
        "p5_shas": sorted(p5_shas),
        "repo_shas": sorted(repo_shas),
        "p5_sizes": sorted({x["size"] for x in p5s}),
        "repo_sizes": sorted({x["size"] for x in repo_by_name[name]}),
        "p5_paths": [x["path"] for x in p5s],
        "repo_paths": [x["path"] for x in repo_by_name[name]],
    })

out["same_basename_no_shared_sha"] = same_name_diff
print("SAME_BASENAME_NO_SHARED_SHA", len(same_name_diff))
for x in same_name_diff:
    print("  ", x["name"], "p5", x["p5_sizes"], "repo", x["repo_sizes"])

# compact summary without full records for print
print("P5_NAMES")
for r in out["trees"]["P5_documents_peak_trade_forensics"]["records"]:
    print(f"  {r['size']:10d} {r['sha256'][:16] if r.get('sha256') else 'NOHASH'} {r['rel']}")

# write compact JSON to /tmp (not repo, not external corpus)
compact = {
    "trees_summary": {k: {"root": v["root"], "exists": v["exists"], "file_count": v["file_count"], "byte_sum": v["byte_sum"]} for k, v in out["trees"].items()},
    "p5_records": out["trees"]["P5_documents_peak_trade_forensics"]["records"],
    "p1_docs_forensics_records": out["trees"]["P1_docs_forensics"]["records"],
    "p1_docs_forensic_records": out["trees"]["P1_docs_forensic"]["records"],
    "p1_forensics_records": [
        {k: r[k] for k in ("path","rel","name","size","sha256","ext","mtime_epoch")}
        for r in out["trees"]["P1_forensics"]["records"]
    ],
    "p1_forensic_records_no_giant_bodies": [
        {k: r[k] for k in ("path","rel","name","size","sha256","ext","mtime_epoch")}
        for r in out["trees"]["P1_forensic"]["records"]
    ],
    "cross_byte_identical_p1_p5": cross,
    "same_basename_no_shared_sha": same_name_diff,
    "p5_desktop_evidence_bound_candidates": desk,
    "errors": out["errors"],
}
dest = Path("/tmp/peak_trade_forensic_discovery_inventory_v1.json")
dest.write_text(json.dumps(compact, indent=2, sort_keys=True), encoding="utf-8")
print("WROTE", dest, "bytes", dest.stat().st_size)
print("ELAPSED", round(time.time()-t0, 1))
